/**
 * Durable per-session GitLab channel state.
 *
 * Persisted with the turn (same mechanism as `OriginChannelState`) so
 * channel stream-event handlers can rebuild a project-bound handle without
 * re-parsing the webhook.
 */
export function emptyGitLabChannelState(overrides = {}) {
    return {
        projectId: null,
        projectPath: "",
        mergeRequestIid: null,
        headSha: null,
        triggeringNoteId: null,
        deliveryId: null,
        eventType: null,
        ...overrides,
    };
}
/** Build the per-turn channel state from a dispatched event's context. */
export function gitlabChannelStateForEvent(input) {
    return emptyGitLabChannelState({
        projectId: input.project.id,
        projectPath: input.project.pathWithNamespace,
        mergeRequestIid: input.mergeRequestIid ?? null,
        headSha: input.headSha ?? null,
        triggeringNoteId: input.triggeringNoteId ?? null,
        deliveryId: input.deliveryId ?? null,
        eventType: input.eventType,
    });
}
